entries[276433] = { ["name"] = "Blut im Wasser", ["text"] = "100 Meter Reichweite\nSofort\nGegner, die zu lang im Wasser verbleiben, werden von Haien gefressen." }
entries[276434] = { ["name"] = "Verwesendes Fleisch", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Instabilität von G'huuns Blutmagie unterdrückt 12 Sek. lang 'Blutruf', wodurch die betroffene Kreatur ohne Regeneration getötet werden kann. Bei Entfernung springt dieser Effekt zu einer Kreatur eines anderen Typs über." }
