entries[277007] = { ["name"] = "Platzendes Geschwür", ["text"] = "500 Meter Reichweite\nSofort\nG'huun ruft 3 platzende Geschwüre hervor. Jedes Geschwür explodiert nach 8 Sek. und fügt den 2 ihm nächsten Zielen 1600 Schattenschaden sowie 30 Sek. lang alle 2 Sek. zusätzlich 565 Schattenschaden zu.\n\nJeder Spielercharakter, der 2 Stapel von ' Platzendes Geschwür ' erreicht, wird zu einem widerwilligen Diener von G'huun und greift seine Verbündeten an, bis er getötet wird." }
